window.products.push({"id":583521,"name":"BirthdayExpress Sonic the Hedgehog Snack Party Pack for 16 Guests, Multi-colored, One Size","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/71TH4D43giL._AC_SL1500_.jpg","description":"This Sonic the Hedgehog Snack Party Pack for 16 guests features 16 Sonic the Hedgehog Dessert Plates, 16 Sonic the Hedgehog 9-ounce Paper Cups, 20 Sonic the Hedgehog Lunch Napkins, 16 Sonic the Hedgehog Paper Cups, and 16 each blue plastic forks and spoons. Invite Sonic, Tails, and the rest of the Sonic gang to your next big birthday bash with Sonic the Hedgehog Party Supplies from BirthdayExpress! With plates, cups, napkins, party kits, favor kits, decorations, and pinatas Sonic will help you create the theme as well as make it easy to clean up. Officially licensed SEGA party supplies.","images":["https://m.media-amazon.com/images/I/71TH4D43giL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"BirthdayExpress","source_asin":"B07BZW8VCW","category_path":"Home & Kitchen"},"sku":"BM-583521","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B07BZW8VCW","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B07BZW8VCW","price_pending":true,"merchant_ready":false});
